    "titan-black-sedan": { name: "Titan Black (Xe 4-5 Chỗ)", brand: "Titan", price: "5.000.000₫", desc: "Phim cách nhiệt Titan Black nhập khẩu từ Mỹ, dòng cơ bản trong 3 dòng phim Titan Window Film, cản tia UV 99.9% và tia hồng ngoại 80-94%. Trọn gói dán cho xe Sedan 4-5 chỗ. Hàng chính hãng Titan Window Film - phân phối bởi AKauto.", specs: [["Dòng phim","Titan Black"],["Cản tia UV","99.9%"],["Cản tia hồng ngoại","80-94%"],["Bảo hành","15 năm"],["Dòng xe áp dụng","Sedan 4-5 chỗ"],["Xuất xứ","Nhập khẩu Mỹ - phân phối bởi AKauto"]] },
    "titan-titanium-sedan": { name: "Titan Titanium (Xe 4-5 Chỗ)", brand: "Titan", price: "7.000.000₫", desc: "Phim cách nhiệt Titan Titanium, dòng trung cấp công nghệ Nano Ceramic, cản tia UV 99.9% và tia hồng ngoại 80-98%. Trọn gói dán cho xe Sedan 4-5 chỗ. Hàng chính hãng Titan Window Film - phân phối bởi AKauto.", specs: [["Dòng phim","Titan Titanium"],["Cản tia UV","99.9%"],["Cản tia hồng ngoại","80-98%"],["Bảo hành","15 năm"],["Dòng xe áp dụng","Sedan 4-5 chỗ"],["Xuất xứ","Nhập khẩu Mỹ - phân phối bởi AKauto"]] },
