    /* ---------- Gotech - Không Camera 360 ---------- */
    "gotech-g4": { name: "Gotech G4", brand: "Gotech", price: "Liên hệ", desc: "Gotech G4 là màn hình ô tô thông minh tích hợp giải trí đa phương tiện, điều khiển giọng nói tiếng Việt (Kiki & GotechGPT) và định vị dẫn đường bằng Google Maps, CarMap. Máy dùng RAM 2GB/ROM 32GB, chip 8 nhân 1.6GHz, chạy Android 10, hỗ trợ CarPlay có dây/không dây, 4G, WiFi phát và tích hợp cảm biến áp suất lốp, camera lùi/hành trình.", specs: [["RAM/ROM","2GB/32GB"],["Chip xử lý","8 nhân 1.6GHz, GPU Mali G52"],["Hệ điều hành","Android 10"],["Màn hình","QLED 2.5D, 1280x720"],["Kết nối","4G, WiFi phát, Bluetooth"],["CarPlay","Có (dây/không dây)"],["Camera 360","Hỗ trợ lắp thêm (không tích hợp sẵn)"],["Âm thanh","DSP 32 kênh"],["Bảo hành","2 năm 1 đổi 1"]] },
    "gotech-gts4": { name: "Gotech GTS4", brand: "Gotech", price: "Liên hệ", desc: "Gotech GTS4 nổi bật với hệ thống cảnh báo lái xe ADAS - BSD (cảnh báo chệch làn, khoảng cách, điểm mù), RAM 4GB/ROM 32GB, chip 8 nhân 1.8GHz chạy Android 12. Máy hỗ trợ CarPlay có dây, kết nối 4G/WiFi, tra cứu phạt nguội và điều khiển giọng nói qua GotechGPT.", specs: [["RAM/ROM","4GB/32GB"],["Chip xử lý","8 nhân 1.8GHz (2x Cortex A75, 6x Cortex A55), GPU Mali G52 kép"],["Hệ điều hành","Android 12"],["Màn hình","QLED 2.5D, 1280x720"],["Kết nối","4G, WiFi, Bluetooth"],["CarPlay","Có (dây)"],["Camera 360","Hỗ trợ lắp thêm (không tích hợp sẵn)"],["Tính năng an toàn","ADAS - cảnh báo chệch làn, va chạm, điểm mù"],["Âm thanh","DSP 32 kênh"],["Bảo hành","2 năm 1 đổi 1"]] },
    "gotech-gt2k-new": { name: "Gotech GT2K New", brand: "Gotech", price: "Liên hệ", desc: "Gotech GT2K New sở hữu màn hình QLED 2K (2000x1200) sắc nét gấp 4 lần HD, thiết kế viền mỏng hiện đại. Máy có RAM 4GB/ROM 64GB, chip 8 nhân 1.87GHz, chạy Android 12, hỗ trợ CarPlay có dây/không dây, 4G, WiFi và điều khiển giọng nói tiếng Việt bằng GotechGPT, Kiki.", specs: [["RAM/ROM","4GB/64GB"],["Chip xử lý","8 nhân 1.87GHz, GPU G52 2 nhân"],["Hệ điều hành","Android 12"],["Màn hình","QLED 2K, 2000x1200"],["Kết nối","4G, WiFi, Bluetooth"],["CarPlay","Có (dây/không dây)"],["Camera 360","Hỗ trợ lắp thêm (không tích hợp sẵn)"],["Bản đồ","Google Maps, Carmap (bản quyền trọn đời)"],["Âm thanh","DSP 32 kênh"],["Bảo hành","2 năm 1 đổi 1"]] },
    "gotech-gt2k-max": { name: "Gotech GT2K MAX", brand: "Gotech", price: "Liên hệ", desc: "Gotech GT2K MAX trang bị màn hình QLED 2K sắc nét gấp 4 lần HD cùng cấu hình mạnh RAM 8GB/ROM 128GB, chip 8 nhân 2.0GHz chạy Android 12. Máy hỗ trợ CarPlay có dây/không dây, 4G, WiFi, cảm biến áp suất lốp và điều khiển giọng nói tiếng Việt.", specs: [["RAM/ROM","8GB/128GB"],["Chip xử lý","8 nhân 2.0GHz (ARM Cortex), GPU G52 2 nhân"],["Hệ điều hành","Android 12"],["Màn hình","QLED 2K, 2000x1200"],["Kết nối","4G, WiFi, Bluetooth"],["CarPlay","Có (dây/không dây)"],["Camera 360","Hỗ trợ lắp thêm (không tích hợp sẵn)"],["Âm thanh","DSP 32 kênh"],["Bảo hành","2 năm 1 đổi 1"]] },
    "gotech-gt-mazda-pro": { name: "Gotech GT Mazda PRO", brand: "Gotech", price: "17.600.000₫", desc: "Gotech GT Mazda PRO là màn hình chuyên dụng cho Mazda, dùng song song 2 hệ điều hành Mazda Connect và Android 12 để giữ nguyên chức năng gốc xe. Máy có RAM 4GB/ROM 64GB, màn hình QLED 2.5D 10.25 inch 1920x720, hỗ trợ CarPlay, 4G, cảm biến áp suất lốp và điều khiển giọng nói tiếng Việt.", specs: [["RAM/ROM","4GB/64GB"],["Chip xử lý","8 nhân 1.8GHz, GPU Mali G52"],["Hệ điều hành","Mazda Connect + Android 12 (song song)"],["Màn hình","QLED 2.5D 10.25 inch, 1920x720"],["Kết nối","4G, WiFi, Bluetooth"],["CarPlay","Có"],["Camera 360","Hỗ trợ lắp thêm (không tích hợp sẵn)"],["Dòng xe tương thích","Mazda 2, 3 (2015-2019), 6 (2015-2019), CX5, CX8"],["Âm thanh","DSP 32 kênh"],["Bảo hành","2 năm 1 đổi 1"]] },
    "gotech-gt-mazda-limited": { name: "Gotech GT Mazda Limited", brand: "Gotech", price: "22.800.000₫", desc: "Gotech GT Mazda Limited là bản nâng cấp của GT Mazda PRO với RAM 6GB/ROM 128GB, vẫn giữ khả năng chạy song song Mazda Connect và Android 12. Máy có màn hình QLED 2.5D 10.25 inch, hỗ trợ CarPlay, 4G, cảm biến áp suất lốp, đa nhiệm chia màn hình và điều khiển giọng nói tiếng Việt.", specs: [["RAM/ROM","6GB/128GB"],["Chip xử lý","8 nhân 1.8GHz, GPU Mali G52"],["Hệ điều hành","Mazda Connect + Android 12 (song song)"],["Màn hình","QLED 2.5D 10.25 inch, 1920x720"],["Kết nối","4G, WiFi, Bluetooth"],["CarPlay","Có"],["Camera 360","Hỗ trợ lắp thêm (không tích hợp sẵn)"],["Dòng xe tương thích","Mazda 2, 3, 6, CX5, CX8"],["Âm thanh","DSP 32 kênh"],["Bảo hành","2 năm 1 đổi 1"]] },

